235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        if (owner.isNew()) {
239	            if (owner.getRegistrationDate() == null) {
240	                owner.setRegistrationDate(LocalDate.now());
241	            }
242	            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
243	            owner.setCustomerCode(generateCustomerCode(owner));
244	            if (isDuplicateTelephone(owner)) {
245	                throw new DuplicateOwnerException(
246	                    "An owner with the same telephone already exists");
247	            }
248	            if (isDuplicateEmail(owner)) {
249	                throw new DuplicateOwnerException(
250	                    "An owner with the same email already exists");
251	            }
252	        }
253	        ownerRepository.save(owner);
254	
255	    }
256	
257	    /**
258	     * Build a customer code for a newly created owner, formatted as
259	     * {@code <UPPERCASE_CITY>-<NNNN>} where NNNN is one more than the number of
260	     * owners already registered in that city, zero-padded to four digits
261	     * (e.g. {@code LONDON-0007}).
262	     */
263	    private String generateCustomerCode(Owner owner) {
264	        String city = owner.getCity();
265	        long existingInCity = ownerRepository.findAll().stream()
266	            .filter(existing -> !existing.getId().equals(owner.getId()))
267	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
268	            .count();
269	        String prefix = city == null ? "" : city.toUpperCase(Locale.ROOT);
270	        return String.format("%s-%04d", prefix, existingInCity + 1);
271	    }
